import ipaddress
import socket
from urllib.parse import urlsplit

import requests
from flask import Blueprint, abort, jsonify, request

bp = Blueprint("unfurl", __name__)
ALLOWED_HOSTS = {"www.youtube.com", "vimeo.com", "www.figma.com"}


@bp.post("/unfurl")
def unfurl():
    raw = request.json.get("url", "")
    parts = urlsplit(raw)
    if parts.scheme != "https" or parts.hostname not in ALLOWED_HOSTS:
        abort(400, "unsupported link")
    for info in socket.getaddrinfo(parts.hostname, 443):
        if not ipaddress.ip_address(info[4][0]).is_global:
            abort(400, "unsupported link")
    resp = requests.get(raw, timeout=5, allow_redirects=False)
    return jsonify(status=resp.status_code, length=len(resp.content))

