import os
import uuid

from flask import Blueprint, current_app, request, send_from_directory
from werkzeug.utils import secure_filename

bp = Blueprint("avatars", __name__)


@bp.post("/avatars")
def upload_avatar():
    f = request.files["avatar"]
    ext = os.path.splitext(secure_filename(f.filename))[1].lower()
    if ext not in {".png", ".jpg", ".jpeg", ".webp"}:
        return {"error": "unsupported type"}, 400
    name = f"{uuid.uuid4().hex}{ext}"
    f.save(os.path.join(current_app.config["AVATAR_DIR"], name))
    return {"avatar": name}, 201


@bp.get("/avatars/<path:name>")
def get_avatar(name):
    return send_from_directory(current_app.config["AVATAR_DIR"], name)

