import json

from django.core.management.base import BaseCommand

from catalog.models import Product


class Command(BaseCommand):
    help = "Load products from a JSON export: manage.py load_products products.json"

    def add_arguments(self, parser):
        parser.add_argument("path")

    def handle(self, *args, path, **options):
        with open(path, encoding="utf-8") as fh:
            rows = json.load(fh)
        for row in rows:
            Product.objects.update_or_create(sku=row.pop("sku"), defaults={**row})
        self.stdout.write(self.style.SUCCESS(f"Loaded {len(rows)} products"))

